def min_time_to_destination(x1, y1, x2, y2, v_max, t, wind1, wind2):
    def distance(x1, y1, x2, y2):
        return math.sqrt((x2 - x1)**2 + (y2 - y1)**2)

    def time_to_reach(wx, wy, vx, vy):
        rel_vx, rel_vy = vx - wx, vy - wy
        speed = math.sqrt(rel_vx**2 + rel_vy**2)
        if speed > v_max:
            return float('inf')
        return distance(x1, y1, x2, y2) / speed if speed > 0 else float('inf')

    wind1_end = (x1 + t * wind1[0], y1 + t * wind1[1])
    wind2_end = (x1 + wind2[0], y1 + wind2[1])

    # Time to reach destination from wind1 start
    t1 = time_to_reach(wind1[0], wind1[1], 0, 0)

    # Time to reach wind1 end and change wind
    if wind1 == wind2:
        t2 = time_to_reach(wind2[0], wind2[1], 0, 0)
    else:
        t2 = distance(x1, y1, wind1_end[0], wind1_end[1]) / v_max + t

    # Time to reach destination from wind2 end
    t3 = time_to_reach(wind2[0], wind2[1], 0, 0)

    return min(t1, t2, t3)

