import math
import sys
from scipy.optimize import minimize_scalar

def min_time_to_destination(x1, y1, x2, y2, v_max, t, wind1, wind2):
    def distance(x, y):
        return math.sqrt((x2 - x)**2 + (y2 - y)**2)

    def travel_time(speed, direction, wind):
        vx, vy = wind
        # relative velocity of the dirigible with respect to wind
        v_relative_x = speed * math.cos(direction) - vx
        v_relative_y = speed * math.sin(direction) - vy
        v_relative_speed = math.sqrt(v_relative_x**2 + v_relative_y**2)
        if v_relative_speed > v_max:
            return float('inf')
        travel_distance = distance(x1 + speed * math.cos(direction), y1 + speed * math.sin(direction))
        return travel_distance / v_relative_speed

    def optimal_time():
        def wind_at_time(time):
            return wind1 if time <= t else wind2

        def travel_time_for_time(time):
            wind = wind_at_time(time)
            # Optimize speed and direction for a given time
            result = minimize_scalar(lambda speed: travel_time(speed, 0, wind), bounds=(0, v_max), method='bounded')
            return result.fun if result.success else float('inf')

        # Find the time when travel time is minimized
        result = minimize_scalar(travel_time_for_time, bounds=(0, t + 1), method='bounded')
        return result.fun if result.success else float('inf')

    return optimal_time()

